DROP VIEW PS_CUR_RT_TYPE_TBL
/
CREATE VIEW PS_CUR_RT_TYPE_TBL (CUR_RT_TYPE, EFFDT, EFF_STATUS, DESCR,
 DESCRSHORT) AS SELECT RT_TYPE , TO_DATE('1900-01-01','YYYY-MM-DD') ,
 'A' , DESCR , DESCRSHORT FROM PS_RT_TYPE_TBL
/